'use strict';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const list = data => Array.isArray(data) ? data : (data?.items || data?.records || []);
const state = {initialized:false, unlocked:false, settings:{}, health:{models:[]}, view:'chat', chats:[], chatId:null, noteId:null, mailId:null, tasks:[], memories:[], notes:[], mails:[], accounts:[], events:[], errands:[], mailQuery:'', category:'flights', transcript:'', dictationTarget:null, busyChat:false, recorder:null, recordChunks:[], recordStart:0, recordTimer:null, cancelRecording:false, routeToken:0, vaultEpoch:0};
const views = {study:['Study arena','Your chapters, evidence and next level.'],updates:['Updates & backups','Keep your app current and your progress safe.'],chat:['Private chat',''],notes:['Meeting notes','Turn conversations into something useful.'],tasks:['Tasks','A clear place for your next move.'],mail:['Mail','Your inbox, with a local encrypted cache.'],calendar:['Calendar','Make room for what matters.'],dictation:['Dictation','Think out loud. Keep the words here.'],memory:['Personal memory','You decide what your AI remembers.'],errands:['Browser errands','Find options, compare sources, make the decision.'],settings:['Settings & privacy','A little control goes a long way.']};
let toastTimer;
function toast(message, error = false) { const el = $('#toast'); el.textContent = String(message); el.classList.toggle('error-toast',error); el.hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.hidden=true,error?9000:4500); }
async function api(path, options = {}) {
  const requestEpoch=state.vaultEpoch, beganUnlocked=state.unlocked;
  const opts={credentials:'same-origin',...options,headers:{...options.headers}};
  if (opts.method && opts.method!=='GET') opts.headers['X-Local-AI']='1';
  if(opts.body && !(opts.body instanceof FormData)){opts.headers['Content-Type']='application/json'; if(typeof opts.body!=='string')opts.body=JSON.stringify(opts.body);}
  const res=await fetch(`/api${path}`,opts);
  if(beganUnlocked && requestEpoch!==state.vaultEpoch)throw new Error('Vault locked. Unlock to continue.');
  if(!res.ok){let data;try{data=await res.json();}catch{data={detail:`Request failed (${res.status})`};} const detail=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data); if((res.status===401||res.status===423)&&state.unlocked){state.unlocked=false;clearPrivateState();showGate();} throw new Error(detail);}
  if(res.status===204)return null;
  const result=options.blob?await res.blob():await res.json();
  if(beganUnlocked && requestEpoch!==state.vaultEpoch)throw new Error('Vault locked. Unlock to continue.');
  return result;
}
const post=(path,body={})=>api(path,{method:'POST',body});
const patch=(path,body)=>api(path,{method:'PATCH',body});
const del=path=>api(path,{method:'DELETE'});
function on(selector,event,callback,root=document){const el=$(selector,root);if(el)el.addEventListener(event,callback);}
function value(form,name){return new FormData(form).get(name)?.toString().trim()||'';}
function checked(form,name){return !!form.elements[name]?.checked;}
async function action(button,work,label='Working…'){if(button?.disabled)return;const original=button?.textContent;const changeLabel=button?.tagName==='BUTTON';if(button){button.disabled=true;if(changeLabel)button.textContent=label;}try{return await work();}catch(error){toast(error.message,true);}finally{if(button?.isConnected){button.disabled=false;if(changeLabel)button.textContent=original;}}}
function stamp(value, options={}){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString(undefined,{month:'short',day:'numeric',...options});}
function dateTime(value){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
function dateInput(value){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:'#';}catch{return '#';}}
function domain(value){try{return new URL(value).hostname;}catch{return 'Source';}}
function empty(title,description,symbol='◇'){return `<div class="empty"><div class="empty-symbol" aria-hidden="true">${symbol}</div><strong>${esc(title)}</strong>${esc(description)}</div>`;}
function heading(name,description,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR PRIVATE WORKSPACE</div><h1>${esc(name)}</h1><p>${esc(description)}</p></div><div class="button-row">${buttons}</div></div>`;}
function modelNotice(){if(state.health.ollama&&state.settings.model)return '';return `<div class="notice">${!state.health.ollama?'Your local AI is not connected. Start Ollama on this computer, then choose a downloaded model.':'Choose a downloaded local model to enable AI replies and summaries.'} <a href="#settings">Open connection settings ↗</a></div>`;}
function networkNotice(){return state.settings.network_enabled?'':`<div class="notice">External connections are off. Local data is still available. Enable email, calendar and browser connections in <a href="#settings">Settings & privacy</a> when you want to connect.</div>`;}
function modal(title,description,body,bind){const dialog=$('#modal');$('#modal-content').innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2><button type="button" class="icon-button" id="modal-close" aria-label="Close dialog">×</button></div>${description?`<p class="modal-intro">${esc(description)}</p>`:''}${body}`;on('#modal-close','click',()=>dialog.close());dialog.showModal();if(bind)bind(dialog);const first=$('input,textarea,select',dialog);first?.focus();}
function closeModal(){$('#modal').close();}
async function download(path,name){const blob=await api(path,{blob:true});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function updateShell(){const name=views[state.view]?.[0]||'Private chat';$('#breadcrumb').textContent=name;$$('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===state.view));$('#network-status').textContent=state.settings.network_enabled?'External connections enabled':'External connections off';$('#model-status').textContent=state.health.ollama?'Local AI connected':'Local AI not connected';$('#model-dot').classList.toggle('off',!state.health.ollama);$('#sidebar-model').textContent=state.settings.model||'Choose a downloaded local model in Settings.';$('#task-count').textContent=state.tasks.filter(t=>t.status!=='done').length||'';}
function showGate(){state.unlocked=false;$('#app').hidden=true;$('#gate').hidden=false;$('#passphrase').value='';$('#passphrase-confirm').value='';$('#gate-error').textContent='';$('#confirm-field').hidden=state.initialized;$('#recovery-warning').hidden=state.initialized;$('#passphrase-confirm').required=!state.initialized;$('#passphrase').minLength=state.initialized?1:12;$('#passphrase').autocomplete=state.initialized?'current-password':'new-password';$('#gate-title').innerHTML=state.initialized?'Welcome back.<br>Your space is locked.':'A little intelligence.<br>Entirely yours.';$('#gate-description').textContent=state.initialized?'Unlock your encrypted vault to pick up where you left off.':'Create a passphrase to encrypt your chats, notes, accounts and memories on this computer.';$('#gate-submit').textContent=state.initialized?'Unlock my space ↗':'Create my private space ↗';$('#passphrase').focus();}
async function enterApp(){state.unlocked=true;$('#gate').hidden=true;$('#app').hidden=false;await refreshSettings();try{state.tasks=list(await api('/tasks'));}catch{}await navigate();maybeAutomaticUpdate();}
async function refreshSettings(){const [settings,health]=await Promise.allSettled([api('/settings'),api('/health')]);if(settings.status==='fulfilled')state.settings=settings.value;if(health.status==='fulfilled')state.health=health.value;updateShell();}
async function navigate(){if(!state.unlocked)return;const view=location.hash.slice(1).split('?')[0]||'study';state.view=views[view]?view:'study';const token=++state.routeToken;$('#sidebar').classList.remove('open');updateShell();$('#content').innerHTML='<div class="loading"><span class="loader"></span>Opening your workspace…</div>';try{const needs={study:[],updates:[],chat:['chats'],notes:['notes'],tasks:['tasks'],mail:['mail','mail/accounts'],calendar:['events'],memory:['memories'],errands:['errands'],dictation:[],settings:[]}[state.view];const data=await Promise.all(needs.map(path=>api(`/${path}${path==='mail'?'?q='+encodeURIComponent(state.mailQuery):''}`)));if(token!==state.routeToken)return;needs.forEach((path,i)=>state[{'mail':'mails','mail/accounts':'accounts','memories':'memories'}[path]||path]=list(data[i]));if(state.view==='chat'&&state.chatId){const chat=await api('/chats/'+encodeURIComponent(state.chatId));state.chats=state.chats.map(c=>c.id===chat.id?chat:c);}if(state.view==='settings')await refreshSettings();if(state.view==='study')await loadStudy();if(state.view==='updates')await loadUpdates();if(token!==state.routeToken)return;render();}catch(error){if(!state.unlocked||token!==state.routeToken)return;$('#content').innerHTML=`${heading(views[state.view][0],views[state.view][1])}<div class="notice">${esc(error.message)}</div><button class="secondary" id="retry-view">Try again</button>`;on('#retry-view','click',navigate);}}
function render(){updateShell();({study:renderStudy,updates:renderUpdates,chat:renderChat,notes:renderNotes,tasks:renderTasks,mail:renderMail,calendar:renderCalendar,dictation:renderDictation,memory:renderMemory,errands:renderErrands,settings:renderSettings}[state.view])();}
function renderChat(){if(!state.unlocked||state.view!=='chat')return;let chat=state.chats.find(c=>c.id===state.chatId);if(state.chatId&&!chat)state.chatId=null;const messages=chat?.messages||[];$('#content').innerHTML=`<section class="chat-layout"><div class="chat-top"><div class="button-row"><span class="badge">✧ &nbsp; On-device chat</span><select id="chat-history" ${state.busyChat?'disabled':''} class="model-select" aria-label="Chat history"><option value="">New conversation</option>${state.chats.map(c=>`<option value="${esc(c.id)}" ${c.id===state.chatId?'selected':''}>${esc(c.title||'Untitled chat')}</option>`).join('')}</select></div><div class="button-row">${chat?'<button class="icon-button" id="delete-chat" aria-label="Delete conversation" title="Delete conversation">⌫</button>':''}<button class="quiet" id="new-chat" ${state.busyChat?'disabled':''}>＋ New chat</button></div></div>${modelNotice()}${messages.length?'':`<div class="chat-hero"><div class="chat-orb" aria-hidden="true">✧</div><div class="eyebrow">A LITTLE SPACE TO THINK</div><h1>What's on your mind, Sultan?</h1><p>Ask a question. Untangle an idea. Work through the next step.<br>Your conversation stays on this computer.</p></div><div class="prompt-grid"><button class="prompt-card" data-prompt="Help me break down a difficult concept. Ask me what I am studying and what part confuses me."><span>◇</span><strong>Understand something</strong><small>Break an idea into clear steps</small></button><button class="prompt-card" data-prompt="Help me plan a focused study session. Start by asking about my goal and available time."><span>▦</span><strong>Make a plan</strong><small>Give the next hour some direction</small></button><button class="prompt-card" data-prompt="Help me think critically about an idea. Ask for the idea, then test its assumptions and weak points."><span>↗</span><strong>Challenge an idea</strong><small>Find the assumptions worth testing</small></button></div>`}<div class="chat-messages" id="chat-messages" aria-live="polite">${messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}"><div class="message-avatar">${m.role==='user'?'S':'✧'}</div><div class="message-content">${esc(m.content)}</div></div>`).join('')}${state.busyChat?'<div class="message assistant"><div class="message-avatar">✧</div><div class="message-content muted"><span class="loader"></span>Thinking on your computer…</div></div>':''}</div><form class="composer" id="chat-form"><textarea name="message" id="chat-message" aria-label="Message your local AI" placeholder="Ask your local AI anything…" required ${state.busyChat?'disabled':''}></textarea><div class="composer-bottom"><label class="toggle-label"><input type="checkbox" name="use_memory" ${state.settings.use_memory?'checked':'disabled'}>Include enabled personal memories</label>${!state.settings.use_memory?'<a class="small" href="#settings">Allow memory in Settings</a>':''}<button type="submit" class="primary" ${state.busyChat?'disabled':''}>${state.busyChat?'Thinking…':'Send ↗'}</button></div></form><p class="chat-disclaimer">Local AI can make mistakes. Check answers before relying on them.</p></section>`;
  on('#chat-history','change',async event=>{state.chatId=event.target.value||null;if(state.chatId){try{const c=await api('/chats/'+encodeURIComponent(state.chatId));state.chats=state.chats.map(x=>x.id===c.id?c:x);}catch(e){toast(e.message,true);}}renderChat();});on('#new-chat','click',()=>{state.chatId=null;renderChat();$('#chat-message').focus();});on('#delete-chat','click',()=>{if(state.busyChat)return;if(confirm('Delete this conversation from your vault?'))action($('#delete-chat'),async()=>{await del('/chats/'+encodeURIComponent(state.chatId));state.chats=state.chats.filter(c=>c.id!==state.chatId);state.chatId=null;renderChat();});});$$('[data-prompt]').forEach(button=>button.addEventListener('click',()=>{$('#chat-message').value=button.dataset.prompt;$('#chat-message').focus();}));on('#chat-message','keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();$('#chat-form').requestSubmit();}});on('#chat-form','submit',async event=>{event.preventDefault();if(state.busyChat)return;const form=event.currentTarget;const message=value(form,'message');if(!message)return;const use_memory=checked(form,'use_memory');state.busyChat=true;const oldId=state.chatId;let active=state.chats.find(c=>c.id===oldId);if(!active){active={id:'pending',title:message.slice(0,55),messages:[]};state.chats.unshift(active);state.chatId=active.id;}const previousMessages=[...(active.messages||[])];let sendFailed=false;active.messages=active.messages||[];active.messages.push({role:'user',content:message});renderChat();try{const result=await post('/chat',{chat_id:oldId,message,use_memory});state.chatId=result.chat_id;state.chats=list(await api('/chats'));const saved=await api('/chats/'+encodeURIComponent(result.chat_id));state.chats=state.chats.map(c=>c.id===saved.id?saved:c);if(!state.chats.some(c=>c.id===saved.id))state.chats.unshift(saved);}catch(error){sendFailed=true;toast(error.message,true);state.chats=state.chats.filter(c=>c.id!=='pending');if(oldId){const existing=state.chats.find(c=>c.id===oldId);if(existing)existing.messages=previousMessages;}state.chatId=oldId;}finally{state.busyChat=false;if(state.view==='chat'&&state.unlocked){renderChat();if(sendFailed)$('#chat-message').value=message;$('#chat-message').focus();}}});if(messages.length)$('#chat-messages')?.lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function renderNotes(){if(!state.unlocked||state.view!=='notes')return;const selected=state.notes.find(n=>n.id===state.noteId)||state.notes[0];state.noteId=selected?.id||null;$('#content').innerHTML=`${heading('Meeting notes','Listen closely. Leave with clear next steps.','<button class="primary" id="new-note">＋ New note</button>')}<div class="split"><section><div class="panel-header"><h3>Your notes</h3><span class="badge">${state.notes.length}</span></div><div class="scroll-list">${state.notes.map(n=>`<button class="list-item ${n.id===state.noteId?'selected':''}" data-note="${esc(n.id)}"><strong>${esc(n.title||'Untitled note')}</strong><small>${stamp(n.updated_at||n.created_at)} ${n.summary?'· Summarised':''}</small></button>`).join('')||empty('A clear page awaits','Create a note or record a meeting.','▤')}</div></section><section class="panel">${selected?`<form id="note-form"><div class="panel-header"><span class="badge">Private note</span><button class="icon-button" type="button" id="delete-note" title="Delete note" aria-label="Delete note">⌫</button></div><label for="note-title">Title</label><input name="title" id="note-title" value="${esc(selected.title)}" required maxlength="200"><label for="note-body">Your notes</label><textarea class="note-editor" name="body" id="note-body" placeholder="The ideas, context and details you want to keep…">${esc(selected.body)}</textarea><label for="note-transcript">Transcript <span class="muted">(optional)</span></label><textarea name="transcript" id="note-transcript" placeholder="Paste a transcript, or record audio with Dictation.">${esc(selected.transcript||'')}</textarea><div class="form-actions"><button class="secondary" type="button" id="record-meeting">♩ Record audio</button><button class="primary" type="submit">Save note</button></div></form><div class="section-divider"></div>${modelNotice()}<div class="button-row"><button class="secondary" id="summarize-note">✧ Summarise & find actions</button>${selected.actions?.length?'<button class="quiet" id="import-actions">＋ Add actions to tasks</button>':''}</div><p class="hint">Your edits are saved before summarising. AI suggestions need your review.</p>${selected.summary?`<section class="summary-section"><h3>Summary</h3><p>${esc(selected.summary)}</p></section>`:''}${selected.decisions?.length?`<section class="summary-section"><h3>Decisions</h3><ul>${selected.decisions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}${selected.actions?.length?`<section class="summary-section"><h3>Suggested next steps</h3><ul>${selected.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}`:empty('Your notes, in one place','Write freely, add a transcript and generate a local AI summary.','▤')}</section></div>`;
 on('#new-note','click',()=>modal('New note','Give this conversation a place to land.',`<form id="new-note-form"><label for="new-note-title">Title</label><input id="new-note-title" name="title" placeholder="e.g. Project discussion" required maxlength="200"><div class="form-actions"><button class="primary" type="submit">Create note</button></div></form>`,()=>on('#new-note-form','submit',event=>{event.preventDefault();action($('button[type=submit]',event.currentTarget),async()=>{const note=await post('/notes',{title:value(event.currentTarget,'title'),body:''});state.notes.unshift(note);state.noteId=note.id;closeModal();renderNotes();});})));$$('[data-note]').forEach(b=>b.addEventListener('click',()=>{state.noteId=b.dataset.note;renderNotes();}));const saveNote=async()=>{const form=$('#note-form');const note=await patch('/notes/'+encodeURIComponent(state.noteId),{title:value(form,'title'),body:form.elements.body.value,transcript:form.elements.transcript.value});state.notes=state.notes.map(n=>n.id===note.id?note:n);return note;};on('#note-form','submit',event=>{event.preventDefault();action($('button[type=submit]',event.currentTarget),async()=>{await saveNote();toast('Note saved.');renderNotes();});});on('#delete-note','click',()=>{if(confirm('Delete this note and its transcript?'))action($('#delete-note'),async()=>{await del('/notes/'+encodeURIComponent(state.noteId));state.notes=state.notes.filter(n=>n.id!==state.noteId);state.noteId=null;renderNotes();});});on('#summarize-note','click',()=>action($('#summarize-note'),async()=>{const saved=await saveNote();const note=await post('/notes/'+encodeURIComponent(saved.id)+'/summarize');state.notes=state.notes.map(n=>n.id===note.id?note:n);renderNotes();toast('Summary ready. Review decisions and actions.');},'Summarising locally…'));on('#import-actions','click',()=>action($('#import-actions'),async()=>{const result=await post('/notes/'+encodeURIComponent(state.noteId)+'/tasks');state.tasks=list(await api('/tasks'));updateShell();toast(`${result.created?.length||0} suggested actions added to Tasks.`);}));on('#record-meeting','click',()=>action($('#record-meeting'),async()=>{const saved=await saveNote();state.dictationTarget=saved.id;location.hash='dictation';}));
}
function taskDialog(task){modal(task?'Edit task':'New task','One specific action is easier to finish.',`<form id="task-form"><label for="task-title">Task</label><input id="task-title" name="title" required maxlength="500" placeholder="What needs to happen?" value="${esc(task?.title||'')}"><div class="form-row"><div><label for="task-status">Status</label><select id="task-status" name="status">${[['ready','Ready'],['in_progress','In progress'],['done','Done']].map(([v,t])=>`<option value="${v}" ${task?.status===v?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="task-due">Due date (optional)</label><input type="date" id="task-due" name="due" value="${esc(task?.due?.slice(0,10)||'')}"></div></div><div class="form-actions"><button class="primary" type="submit">${task?'Save changes':'Add task'}</button></div></form>`,()=>on('#task-form','submit',event=>{event.preventDefault();const form=event.currentTarget;action($('button[type=submit]',form),async()=>{const body={title:value(form,'title'),status:value(form,'status'),due:value(form,'due')||''};if(task){await patch('/tasks/'+encodeURIComponent(task.id),body);}else await post('/tasks',body);state.tasks=list(await api('/tasks'));closeModal();renderTasks();updateShell();});}));}
function renderTasks(){if(!state.unlocked||state.view!=='tasks')return;const columns=[['ready','Ready',''],['in_progress','In progress','progress'],['done','Done','done']];$('#content').innerHTML=`${heading('A little more organised.','Start with one thing. Move it forward.','<button class="primary" id="new-task">＋ Add task</button>')}<div class="board">${columns.map(([status,title,color])=>`<section class="board-column"><div class="column-heading"><span class="column-dot ${color}"></span>${title}<span class="badge">${state.tasks.filter(t=>t.status===status).length}</span></div>${state.tasks.filter(t=>t.status===status).map(t=>`<article class="task-card"><h3>${esc(t.title)}</h3>${t.due?`<div class="task-meta">◷ ${esc(stamp(t.due))}</div>`:''}<div class="task-card-footer"><select aria-label="Status for ${esc(t.title)}" data-task-status="${esc(t.id)}">${columns.map(([v,l])=>`<option value="${v}" ${v===t.status?'selected':''}>${l}</option>`).join('')}</select><div><button class="icon-button" data-task-edit="${esc(t.id)}" aria-label="Edit task">✎</button><button class="icon-button" data-task-delete="${esc(t.id)}" aria-label="Delete task">×</button></div></div></article>`).join('')||'<p class="section-caption">Room for the next thing.</p>'}</section>`).join('')}</div>`;on('#new-task','click',()=>taskDialog());$$('[data-task-edit]').forEach(b=>b.addEventListener('click',()=>taskDialog(state.tasks.find(t=>t.id===b.dataset.taskEdit))));$$('[data-task-status]').forEach(select=>select.addEventListener('change',async()=>{select.disabled=true;try{const t=await patch('/tasks/'+encodeURIComponent(select.dataset.taskStatus),{status:select.value});state.tasks=state.tasks.map(x=>x.id===t.id?t:x);renderTasks();updateShell();}catch(e){toast(e.message,true);select.disabled=false;}}));$$('[data-task-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this task?'))action(b,async()=>{await del('/tasks/'+encodeURIComponent(b.dataset.taskDelete));state.tasks=state.tasks.filter(t=>t.id!==b.dataset.taskDelete);renderTasks();updateShell();});}));}
function memoryDialog(memory){modal(memory?'Edit memory':'Add a personal memory','Write facts or preferences you want to share with your local AI. You can change or delete them at any time.',`<form id="memory-form"><label for="memory-text">Memory</label><textarea id="memory-text" name="text" required placeholder="e.g. I study mathematics and data science. Explain unfamiliar terms with examples.">${esc(memory?.text||'')}</textarea><label class="toggle-label"><input name="enabled" type="checkbox" ${memory?.enabled!==false?'checked':''}>Enable this memory for chats where I choose to include memory.</label><div class="form-actions"><button class="primary" type="submit">Save memory</button></div></form>`,()=>on('#memory-form','submit',event=>{event.preventDefault();const form=event.currentTarget;action($('button[type=submit]',form),async()=>{const data={text:value(form,'text'),enabled:checked(form,'enabled')};if(memory)await patch('/memories/'+encodeURIComponent(memory.id),data);else await post('/memories',data);state.memories=list(await api('/memories'));closeModal();renderMemory();});}));}
