function eventDialog(event){const now=new Date();now.setMinutes(Math.ceil(now.getMinutes()/30)*30,0,0);const later=new Date(now.getTime()+3600000);modal(event?'Edit event':'New event','Local events are stored in your encrypted vault. Export an .ics file to add them elsewhere.',`<form id="event-form"><label for="event-title">Title</label><input name="title" id="event-title" required value="${esc(event?.title||'')}" placeholder="What is happening?"><div class="form-row"><div><label for="event-start">Starts</label><input name="start" id="event-start" type="datetime-local" required value="${dateInput(event?.start||now)}"></div><div><label for="event-end">Ends</label><input name="end" id="event-end" type="datetime-local" required value="${dateInput(event?.end||later)}"></div></div><p class="hint">Times use your computer’s time zone (${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}).</p><label for="event-location">Location (optional)</label><input name="location" id="event-location" value="${esc(event?.location||'')}"><label for="event-description">Notes (optional)</label><textarea name="description" id="event-description">${esc(event?.description||'')}</textarea><div class="form-actions"><button class="primary" type="submit">${event?'Save event':'Add event'}</button></div></form>`,()=>on('#event-form','submit',e=>{e.preventDefault();const form=e.currentTarget;action($('button[type=submit]',form),async()=>{const start=new Date(value(form,'start')),end=new Date(value(form,'end'));if(end<=start)throw new Error('The event must end after it starts.');const body={title:value(form,'title'),start:start.toISOString(),end:end.toISOString(),location:value(form,'location'),description:form.elements.description.value};if(event)await patch('/events/'+encodeURIComponent(event.id),body);else await post('/events',body);state.events=list(await api('/events'));closeModal();renderCalendar();});}));}
async function caldavDialog(){let config={};try{config=await api('/calendar/config');}catch(e){toast(e.message,true);return;}modal('Import from CalDAV','Pull events from a calendar collection. This is a read-only import; local edits do not sync back.',`<form id="caldav-form"><label for="caldav-url">Calendar collection URL</label><input name="url" id="caldav-url" type="url" required placeholder="https://calendar.example.com/your/calendar/" value="${esc(config.url||'')}"><label for="caldav-user">Username</label><input name="username" id="caldav-user" required value="${esc(config.username||'')}"><label for="caldav-password">App password ${config.has_password?'(saved; blank keeps it)':''}</label><input name="password" id="caldav-password" type="password" autocomplete="new-password"><label for="caldav-timezone">Time zone for floating events</label><input name="timezone" id="caldav-timezone" value="${esc(Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Dubai')}" required><p class="field-help">Use a final HTTPS calendar collection URL, not a server home page. An imported copy covers the configured date window; remote deletions are not automatically mirrored.</p><div class="form-actions"><button class="primary" type="submit">Connect & import</button></div></form>`,()=>on('#caldav-form','submit',event=>{event.preventDefault();const form=event.currentTarget;action($('button[type=submit]',form),async()=>{const result=await post('/calendar/sync',Object.fromEntries(new FormData(form)));state.events=list(await api('/events'));closeModal();renderCalendar();toast(`${result.imported||0} events imported. ${result.message||''} ${(result.warnings||[]).join(' ')}`,!!result.warnings?.length);},'Importing…');}));}
function renderCalendar(){if(!state.unlocked||state.view!=='calendar')return;const sorted=[...state.events].sort((a,b)=>new Date(a.start)-new Date(b.start));$('#content').innerHTML=`${heading('Make time for it.','Your calendar, kept close. Add events or import an existing calendar.','<button class="secondary" id="caldav-connect">CalDAV import</button><button class="primary" id="new-event">＋ New event</button>')}<section class="panel"><div class="panel-header"><div><h3>Your agenda</h3><p class="section-caption no-margin">${sorted.length} events · ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</p></div><div class="button-row"><label class="file-label">Import .ics<input type="file" accept=".ics,text/calendar" id="import-calendar" aria-label="Import calendar ICS file"></label><button class="quiet" id="export-calendar">Export .ics ↗</button></div></div>${sorted.map(event=>{const d=new Date(event.start);return `<article class="event-card"><div class="event-date"><span>${esc(stamp(event.start,{day:undefined,month:'short'}))}</span><strong>${Number.isNaN(d.getTime())?'—':d.getDate()}</strong></div><div><h3>${esc(event.title)}</h3><p>◷ ${esc(dateTime(event.start))} → ${esc(dateTime(event.end))}</p>${event.location?`<p>⌖ ${esc(event.location)}</p>`:''}${event.description?`<p class="event-description">${esc(event.description)}</p>`:''}${event.source||event.caldav_url?'<p class="hint">Imported calendar event</p>':''}</div><div class="event-actions"><button class="icon-button" data-event-edit="${esc(event.id)}" title="Edit local copy" aria-label="Edit event">✎</button><button class="icon-button" data-event-delete="${esc(event.id)}" title="Delete local copy" aria-label="Delete event">×</button></div></article>`;}).join('')||empty('Some breathing room','Add a new event, import an .ics file, or connect a CalDAV calendar.','▦')}</section><p class="hint">Local edits stay local. Calendar export creates an unencrypted .ics file; store it somewhere you trust.</p>`;on('#new-event','click',()=>eventDialog());on('#caldav-connect','click',caldavDialog);on('#export-calendar','click',()=>action($('#export-calendar'),()=>download('/calendar/export','sultan-calendar.ics')));on('#import-calendar','change',async event=>{const file=event.target.files[0];if(!file)return;event.target.disabled=true;const data=new FormData();data.append('file',file);data.append('timezone',Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Dubai');try{const result=await post('/calendar/import',data);state.events=list(await api('/events'));renderCalendar();toast(`${result.imported||0} events imported. ${(result.warnings||[]).join(' ')}`,!!result.warnings?.length);}catch(error){toast(error.message,true);event.target.disabled=false;event.target.value='';}});$$('[data-event-edit]').forEach(b=>b.addEventListener('click',()=>eventDialog(state.events.find(e=>e.id===b.dataset.eventEdit))));$$('[data-event-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this event from your local calendar?'))action(b,async()=>{await del('/events/'+encodeURIComponent(b.dataset.eventDelete));state.events=state.events.filter(e=>e.id!==b.dataset.eventDelete);renderCalendar();});}));}
function renderDictation(){if(!state.unlocked||state.view!=='dictation')return;$('#content').innerHTML=`${heading('Say it in your own words.','Record a thought or a meeting. Transcription runs locally after recording.')}${!state.health.speech_ready?'<div class="notice">Local speech transcription needs a downloaded faster-whisper model. Set the model folder in <a href="#settings">Settings & privacy</a>. Recording uses your microphone, with no browser speech service.</div>':''}${state.dictationTarget?'<div class="notice good">Meeting note selected. After transcription, use “Add to meeting note” to save the transcript there.</div>':''}<div class="grid-2"><section class="panel record-area"><div class="eyebrow">LOCAL SPEECH TO TEXT</div><h2>A place to think out loud.</h2><p class="section-caption">Microphone audio is transcribed on this computer.</p><button class="record-button ${state.recorder?.state==='recording'?'recording':''}" id="record-button" aria-label="${state.recorder?.state==='recording'?'Stop recording':'Start recording'}">${state.recorder?.state==='recording'?'■':'♩'}</button><div class="record-timer" id="record-time">00:00</div><div class="waveform ${state.recorder?.state==='recording'?'recording-wave':''}" id="record-wave" aria-hidden="true">${'<i></i>'.repeat(23)}</div><p id="record-status" class="section-caption">${state.recorder?.state==='recording'?'Recording. Click the square to stop.':'Ready when you are. Click to record.'}</p><div class="record-toolbar"><label class="file-label">Upload audio<input id="upload-audio" type="file" accept="audio/*,video/webm" aria-label="Upload audio to transcribe"></label></div><p class="field-help">Please get permission before recording other people.<br>Audio is removed from the server’s temporary files after transcription.</p></section><section class="panel"><div class="panel-header"><h3>Your transcript</h3><span class="badge">Editable</span></div><label for="speech-language">Spoken language</label><select id="speech-language"><option value="auto">Detect automatically</option><option value="en">English</option><option value="ar">Arabic</option><option value="fr">French</option><option value="es">Spanish</option><option value="hi">Hindi</option><option value="ur">Urdu</option></select><label for="dictation-transcript">Transcript</label><textarea id="dictation-transcript" rows="12" placeholder="Your words will appear here after transcription…">${esc(state.transcript)}</textarea><div class="form-actions"><button class="quiet" id="copy-transcript">Copy</button><button class="primary" id="save-transcript">${state.dictationTarget?'Add to meeting note':'Save as a note'}</button></div><p class="hint">Transcripts can contain mistakes. Edit names and technical terms before saving.</p></section></div>`;$('#speech-language').value=state.settings.language||'auto';on('#record-button','click',()=>{if(state.recorder?.state==='recording')stopRecording(false);else startRecording();});on('#dictation-transcript','input',event=>state.transcript=event.target.value);on('#upload-audio','change',event=>{const file=event.target.files[0];if(file)transcribe(file);});on('#copy-transcript','click',()=>action($('#copy-transcript'),async()=>{await navigator.clipboard.writeText($('#dictation-transcript').value);toast('Transcript copied.');}));on('#save-transcript','click',()=>{state.transcript=$('#dictation-transcript').value;if(!state.transcript.trim()){toast('Record or add a transcript first.',true);return;}if(state.dictationTarget){action($('#save-transcript'),async()=>{const id=state.dictationTarget;const note=await api('/notes').then(list).then(xs=>xs.find(n=>n.id===id));if(!note)throw new Error('The selected meeting note no longer exists.');await patch('/notes/'+encodeURIComponent(id),{transcript:[note.transcript,state.transcript].filter(Boolean).join('\n\n')});state.noteId=id;state.dictationTarget=null;state.transcript='';location.hash='notes';toast('Transcript added to your meeting note.');});}else modal('Save transcript','Create a note you can summarise and return to.',`<form id="save-transcript-form"><label for="transcript-title">Note title</label><input name="title" id="transcript-title" required value="Voice note · ${esc(stamp(new Date()))}"><div class="form-actions"><button class="primary" type="submit">Save note</button></div></form>`,()=>on('#save-transcript-form','submit',event=>{event.preventDefault();const form=event.currentTarget;action($('button[type=submit]',form),async()=>{const note=await post('/notes',{title:value(form,'title'),body:'',transcript:state.transcript});state.noteId=note.id;state.transcript='';closeModal();location.hash='notes';toast('Transcript saved as a note.');});}));});}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Microphone recording is unavailable. Use Edge or Chrome at http://127.0.0.1, or upload an audio file.',true);return;}const button=$('#record-button'),captureEpoch=state.vaultEpoch,captureRoute=state.routeToken;let stream;button.disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!state.unlocked||state.vaultEpoch!==captureEpoch||state.view!=='dictation'||state.routeToken!==captureRoute){stream.getTracks().forEach(t=>t.stop());return;}const preferred=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));const recorder=new MediaRecorder(stream,preferred?{mimeType:preferred}:{});state.recorder=recorder;const chunks=[];state.recordChunks=chunks;state.cancelRecording=false;recorder.addEventListener('dataavailable',event=>{if(event.data.size&&state.unlocked&&state.vaultEpoch===captureEpoch)chunks.push(event.data);});recorder.addEventListener('stop',async()=>{stream.getTracks().forEach(t=>t.stop());clearInterval(state.recordTimer);const type=recorder.mimeType||'audio/webm';const blob=new Blob(chunks,{type});chunks.length=0;if(state.recordChunks===chunks)state.recordChunks=[];if(state.recorder===recorder)state.recorder=null;button.disabled=false;if(state.cancelRecording||!state.unlocked||state.vaultEpoch!==captureEpoch||state.routeToken!==captureRoute)return;if(state.view==='dictation')renderDictation();await transcribe(new File([blob],type.includes('mp4')?'recording.m4a':'recording.webm',{type}));});recorder.start(1000);state.recordStart=Date.now();renderDictation();state.recordTimer=setInterval(()=>{const seconds=Math.floor((Date.now()-state.recordStart)/1000);const el=$('#record-time');if(el)el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(seconds>=1800){stopRecording(false);toast('Recording stopped at 30 minutes. Transcription is starting.');}},1000);}catch(error){stream?.getTracks().forEach(t=>t.stop());if(state.unlocked)toast(`Microphone: ${error.message}`,true);}finally{if(button.isConnected)button.disabled=false;}}
function stopRecording(cancel=false){state.cancelRecording=cancel;if(state.recorder?.state==='recording'){state.recorder.stop();state.recorder.stream.getTracks().forEach(t=>t.stop());}clearInterval(state.recordTimer);}
async function transcribe(file){const button=$('#record-button'),upload=$('#upload-audio');if(file.size>100*1024*1024){toast('Audio must be smaller than 100 MB.',true);return;}if(button)button.disabled=true;if(upload)upload.disabled=true;const status=$('#record-status');if(status)status.textContent='Transcribing on your computer. This may take a little while…';try{const data=new FormData();data.append('file',file);data.append('language',$('#speech-language')?.value||'auto');const result=await post('/transcribe',data);state.transcript=[state.transcript,result.text].filter(Boolean).join('\n\n');if(state.view==='dictation'&&state.unlocked){renderDictation();toast('Transcript ready. Review it before saving.');}}catch(error){toast(error.message,true);if(status)status.textContent='Transcription failed. Your existing transcript is unchanged.';}finally{if(button?.isConnected)button.disabled=false;if(upload?.isConnected){upload.disabled=false;upload.value='';}}}
function renderErrands(){if(!state.unlocked||state.view!=='errands')return;const hints={flights:'e.g. Flights from Dubai to Tokyo, 10–17 December, one adult, economy, one checked bag',shopping:'e.g. Compare 27-inch 4K monitors available in UAE under AED 1,500, with USB-C charging',reservations:'e.g. Restaurants in Abu Dhabi with outdoor seating for four, Friday evening',general:'What would you like to research? Include your constraints and location.'};$('#content').innerHTML=`${heading('Let’s find your options.','Research flights, shopping and reservations, with the sources in view.')}${networkNotice()}<section class="research-form"><div class="tab-row" role="group" aria-label="Research category">${[['flights','✈ Flights'],['shopping','▱ Shopping'],['reservations','▦ Reservations'],['general','↗ Anything else']].map(([v,t])=>`<button class="chip ${state.category===v?'active':''}" data-category="${v}">${t}</button>`).join('')}</div><form id="research-form"><label for="research-query">What are you looking for?</label><textarea name="query" id="research-query" required maxlength="2000" placeholder="${esc(hints[state.category])}"></textarea><div class="composer-bottom"><p class="hint">Your query is sent to DuckDuckGo. Results are saved locally.</p><button class="primary" type="submit">Review & research ↗</button></div></form></section><div class="notice good">Use this to build a shortlist. Prices, seats and reservation availability need checking on the provider’s site. You make bookings and purchases yourself.</div><div class="panel-header"><h2>Your research</h2><span class="badge">${state.errands.length} saved</span></div>${state.errands.map(errand=>`<section class="research-result panel"><div class="research-heading"><div><span class="badge">${esc(errand.category||'general')}</span><h3>${esc(errand.query)}</h3><p class="hint">${esc(dateTime(errand.created_at))}</p></div><button class="icon-button" data-errand-delete="${esc(errand.id)}" aria-label="Delete saved research">×</button></div>${errand.warning?`<div class="notice">${esc(errand.warning)} ${errand.search_url?`<a href="${esc(safeURL(errand.search_url))}" target="_blank" rel="noopener noreferrer">Open search yourself ↗</a>`:''}</div>`:''}<div class="source-grid">${(errand.results||[]).map((result,index)=>`<div class="source-card"><a href="${esc(safeURL(result.url))}" target="_blank" rel="noopener noreferrer"><span class="source-domain">${index+1} · ${esc(domain(result.url))} ↗</span><strong>${esc(result.title)}</strong></a><p>${esc(result.snippet)}</p><button class="quiet" data-read-url="${esc(result.url)}">Read page text</button></div>`).join('')}</div>${!errand.results?.length&&!errand.warning?'<p class="section-caption">No results saved for this search.</p>':''}${errand.summary?`<section class="summary-section"><h3>Local AI summary</h3><p>${esc(errand.summary)}</p><p class="hint">This summary uses saved search results. Open sources to verify details.</p></section>`:''}<div class="form-actions"><button class="secondary" data-errand-summarize="${esc(errand.id)}" ${!errand.results?.length?'disabled':''}>✧ ${errand.summary?'Refresh local summary':'Summarise locally'}</button></div></section>`).join('')||empty('A shortlist starts here','Research an errand and keep the sources together.','↗')}`;$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;renderErrands();}));on('#research-form','submit',event=>{event.preventDefault();const form=event.currentTarget;const query=value(form,'query');if(!confirm(`Research this query on DuckDuckGo?\n\n${query}\n\nThe query leaves your computer. Results will be stored in your encrypted vault.`))return;action($('button[type=submit]',form),async()=>{const result=await post('/errands/research',{query,category:state.category});state.errands.unshift(result);renderErrands();toast(result.results?.length?'Research saved. Open sources to check details.':'Search completed. Review the search notice.');},'Researching…');});$$('[data-errand-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this saved research?'))action(b,async()=>{await del('/errands/'+encodeURIComponent(b.dataset.errandDelete));state.errands=state.errands.filter(e=>e.id!==b.dataset.errandDelete);renderErrands();});}));$$('[data-errand-summarize]').forEach(b=>b.addEventListener('click',()=>action(b,async()=>{const result=await post('/errands/'+encodeURIComponent(b.dataset.errandSummarize)+'/summarize');state.errands=state.errands.map(e=>e.id===result.id?result:e);renderErrands();},'Summarising locally…')));$$('[data-read-url]').forEach(b=>b.addEventListener('click',()=>{const url=b.dataset.readUrl;if(!confirm(`Read this public webpage?\n\n${url}\n\nYour computer will connect to ${domain(url)}. No account cookies are sent.`))return;action(b,async()=>{const result=await post('/errands/read',{url});modal(result.title||'Source text',result.url,`<div class="prose">${esc(result.text)}</div><div class="form-actions"><a class="secondary" href="${esc(safeURL(result.url))}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div>`);},'Reading…');}));}
function renderSettings(){if(!state.unlocked||state.view!=='settings')return;const settings=state.settings;const models=state.health.models||[];$('#content').innerHTML=`${heading('Your AI. Your rules.','Keep the intelligence here. Choose what can connect outside.','<button class="secondary" id="refresh-health">↻ Check connection</button>')}<div class="settings-grid"><div><section class="panel settings-section"><div class="panel-header"><h2>Local intelligence</h2><span class="badge ${state.health.ollama?'':'amber'}">${state.health.ollama?'Connected':'Needs setup'}</span></div><p class="section-caption">Connects only to Ollama on this computer.</p><form id="ai-settings-form"><label for="settings-model">Downloaded local model</label><select name="model" id="settings-model"><option value="">Choose a model</option>${models.map(m=>{const name=typeof m==='string'?m:m.name;return `<option value="${esc(name)}" ${settings.model===name?'selected':''}>${esc(name)}</option>`;}).join('')}${settings.model&&!models.some(m=>(typeof m==='string'?m:m.name)===settings.model)?`<option value="${esc(settings.model)}" selected>${esc(settings.model)} (not currently detected)</option>`:''}</select><p class="field-help">Install Ollama, run it with cloud features disabled, and download a model. No cloud AI fallback is used.</p><label for="settings-speech">Local faster-whisper model folder</label><input name="speech_model_path" id="settings-speech" value="${esc(settings.speech_model_path||'')}" placeholder="C:\\Users\\you\\models\\whisper-base"><p class="hint">Point to a downloaded CTranslate2/faster-whisper model directory. Transcription does not download models.</p><label for="settings-language">Default speech language</label><select id="settings-language" name="language">${[['auto','Detect automatically'],['en','English'],['ar','Arabic'],['fr','French'],['es','Spanish'],['hi','Hindi'],['ur','Urdu']].map(([v,t])=>`<option value="${v}" ${settings.language===v?'selected':''}>${t}</option>`).join('')}</select><div class="form-actions"><button type="submit" class="primary">Save AI settings</button></div></form></section><section class="panel settings-section"><h2>Privacy controls</h2><p class="section-caption">External connections start off. Enable them for email, CalDAV and research.</p><form id="privacy-form"><label class="toggle-label"><input name="network_enabled" type="checkbox" ${settings.network_enabled?'checked':''}><span><strong>Allow external connections</strong>Email and calendar sync connect to providers. Browser research sends your query to a search engine and can fetch selected public pages. Local AI stays local.</span></label><label class="toggle-label"><input name="use_memory" type="checkbox" ${settings.use_memory?'checked':''}><span><strong>Allow memory in chat</strong>Enabled memories are available only when you also check the memory option for a chat message. They are never saved automatically.</span></label><label for="settings-lock">Auto-lock after inactivity</label><select name="auto_lock_minutes" id="settings-lock">${[1,5,10,15,30,60].map(v=>`<option value="${v}" ${Number(settings.auto_lock_minutes)===v?'selected':''}>${v} minute${v===1?'':'s'}</option>`).join('')}</select><p class="hint">Locking clears the displayed workspace and releases the vault key.</p><div class="form-actions"><button type="button" class="secondary" id="settings-lock-now">Lock now</button><button type="submit" class="primary">Save privacy settings</button></div></form></section><section class="panel danger-zone"><h2>Data controls</h2><p class="section-caption">Create a readable export or remove your saved content.</p><div class="button-row"><button class="secondary" id="export-data">Export my data ↗</button><button class="danger" id="delete-data">Delete all content</button></div><p class="field-help">An export is an unencrypted JSON file. Provider credentials are excluded. Deleting content keeps your settings; it cannot erase previous exports or copies held by providers.</p></section></div><div><section class="panel settings-section"><div class="eyebrow">THE PRIVACY BASICS</div><h2>Close to home.</h2><div class="privacy-grid"><div class="privacy-stat"><strong>On-device AI</strong><p>Ollama for chat. Faster-whisper for speech.</p></div><div class="privacy-stat"><strong>Encrypted vault</strong><p>Your passphrase protects saved content.</p></div><div class="privacy-stat"><strong>No telemetry</strong><p>No analytics, remote fonts or tracking scripts.</p></div></div><div class="check-row"><span>Local model</span><span class="badge ${state.health.ollama?'':'amber'}">${state.health.ollama?'Ready':'Not ready'}</span></div><div class="check-row"><span>Speech model</span><span class="badge ${state.health.speech_ready?'':'amber'}">${state.health.speech_ready?'Ready':'Not ready'}</span></div><div class="check-row"><span>External connections</span><span class="badge">${settings.network_enabled?'Enabled':'Off'}</span></div><div class="check-row"><span>Personal memory in chat</span><span class="badge">${settings.use_memory?'Allowed':'Off'}</span></div></section><section class="panel settings-section"><h3>First-time setup</h3><p class="field-help">1. Install Python and Ollama.<br>2. Disable Ollama cloud features.<br>3. Download a local model with Ollama.<br>4. Choose that model here.<br>5. Download a speech model to enable dictation.</p><p class="field-help">See the included README for Windows commands and provider setup. This app cannot install software or models on your computer from this page.</p></section><section class="panel"><h3>What “local” means</h3><p class="field-help">Chat, summaries, memory and transcription run on your computer after setup. Sending email, syncing a calendar and researching live websites necessarily contact the relevant services.</p><p class="field-help">Vault encryption protects saved records, not a compromised computer or screenshots. Keep your operating system and disk encryption enabled.</p></section></div></div>`;on('#refresh-health','click',()=>action($('#refresh-health'),async()=>{await refreshSettings();renderSettings();toast('Connection checked.');}));on('#ai-settings-form','submit',event=>{event.preventDefault();const form=event.currentTarget;action($('button[type=submit]',form),async()=>{state.settings=await patch('/settings',{model:value(form,'model'),speech_model_path:value(form,'speech_model_path'),language:value(form,'language')});await refreshSettings();renderSettings();toast('Local AI settings saved.');});});on('#privacy-form','submit',event=>{event.preventDefault();const form=event.currentTarget;action($('button[type=submit]',form),async()=>{state.settings=await patch('/settings',{network_enabled:checked(form,'network_enabled'),use_memory:checked(form,'use_memory'),auto_lock_minutes:Number(value(form,'auto_lock_minutes'))});resetIdleTimer();updateShell();toast('Privacy settings saved.');});});on('#settings-lock-now','click',lockVault);on('#export-data','click',()=>{if(confirm('Export your data as unencrypted JSON?\n\nAnyone with this file can read it. Keep the downloaded file somewhere you trust.'))action($('#export-data'),()=>download('/export','sultan-local-ai-export.json'));});on('#delete-data','click',()=>{if(prompt('This deletes your saved chats, notes, tasks, memories, email accounts, email cache, events and research from this vault. Previous exports and device backups are not erased.\n\nType DELETE to continue:')==='DELETE')action($('#delete-data'),async()=>{await del('/data');clearStudy();state.chats=[];state.chatId=null;state.tasks=[];state.memories=[];state.notes=[];state.noteId=null;state.mails=[];state.accounts=[];state.mailId=null;state.events=[];state.errands=[];state.transcript='';state.dictationTarget=null;updateShell();toast('Saved content deleted.');});});}
let idleTimer,lastTouch=0,lastActivity=Date.now(),idleBusy=false;
function clearPrivateState(){state.vaultEpoch++;clearStudy();stopRecording(true);clearTimeout(idleTimer);state.chatId=null;state.noteId=null;state.mailId=null;state.dictationTarget=null;state.transcript='';state.mailQuery='';state.recordChunks.length=0;state.recordChunks=[];for(const key of ['chats','tasks','memories','notes','mails','accounts','events','errands'])state[key]=[];state.settings={};state.health={models:[]};state.busyChat=false;state.routeToken++;$('#content').replaceChildren();$('#modal-content').replaceChildren();if($('#modal').open)closeModal();$('#toast').hidden=true;}
async function lockVault(){if(idleBusy)return;idleBusy=true;state.unlocked=false;clearPrivateState();showGate();try{await post('/lock');}catch(error){if(!/locked|authentication|unauthorized/i.test(error.message))toast(error.message,true);}finally{idleBusy=false;}}
function resetIdleTimer(){clearTimeout(idleTimer);if(!state.unlocked)return;const minutes=Number(state.settings.auto_lock_minutes)||15;idleTimer=setTimeout(lockVault,minutes*60000);}
function activity(){if(!state.unlocked)return;const now=Date.now();if(now-lastActivity>=(Number(state.settings.auto_lock_minutes)||15)*60000){lockVault();return;}lastActivity=now;resetIdleTimer();if(now-lastTouch>=Math.min(60000,(Number(state.settings.auto_lock_minutes)||15)*20000)){lastTouch=now;post('/touch').catch(error=>{if(state.unlocked)toast(error.message,true);});}}
async function checkLockAfterBackground(){if(!state.unlocked)return;const minutes=Number(state.settings.auto_lock_minutes)||15;if(Date.now()-lastActivity>=minutes*60000){await lockVault();return;}try{const status=await api('/status');if(!status.unlocked){state.unlocked=false;clearPrivateState();showGate();}}catch{}}
async function boot(){const today=new Date();$('#today').textContent=today.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});on('#gate-form','submit',event=>{event.preventDefault();const form=event.currentTarget;$('#gate-error').textContent='';const passphrase=$('#passphrase').value;if(!state.initialized&&passphrase!==$('#passphrase-confirm').value){$('#gate-error').textContent='The passphrases do not match.';return;}const button=$('#gate-submit');button.disabled=true;button.textContent='Opening your vault…';(async()=>{try{await post(state.initialized?'/unlock':'/setup',{passphrase});state.initialized=true;form.reset();lastActivity=Date.now();lastTouch=Date.now();await enterApp();resetIdleTimer();}catch(error){$('#gate-error').textContent=error.message;$('#passphrase').value='';$('#passphrase-confirm').value='';}finally{button.disabled=false;button.textContent=state.initialized?'Unlock my space ↗':'Create my private space ↗';}})();});on('#lock-button','click',lockVault);on('#menu-button','click',()=>$('#sidebar').classList.toggle('open'));window.addEventListener('hashchange',()=>{if(state.recorder?.state==='recording'){stopRecording(true);toast('Recording stopped when leaving dictation. Record again to transcribe audio.');}navigate();});for(const event of ['pointerdown','keydown','scroll'])document.addEventListener(event,activity,{passive:true,capture:true});document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkLockAfterBackground();});window.addEventListener('focus',checkLockAfterBackground);window.addEventListener('beforeunload',()=>stopRecording(true));try{const status=await api('/status');state.initialized=status.initialized;if(status.unlocked){lastActivity=Date.now();await enterApp();resetIdleTimer();}else showGate();}catch(error){$('#gate').hidden=false;$('#gate-description').textContent='The local server is unavailable. Start the app with the included launcher, then reload this page.';$('#gate-form').hidden=true;$('#gate-title').textContent='Connect your local workspace.';$('#gate-error').textContent=error.message;}}
boot();
